import threading
def task_func(file_list):
    exit_codes = []
    def run_file(file):
        try:
            process = subprocess.Popen([file])
            process.wait()
            exit_codes.append(process.returncode)
        except Exception:
            exit_codes.append(-1)
    threads = []
    for file in file_list:
        t = threading.Thread(target=run_file, args=(file,))
        threads.append(t)
        t.start()
    for t in threads:
        t.join()
    return exit_codes

